 PSECURITY_DESCRIPTOR sd; check(ConvertStringSecurityDescriptorToSecurityDescriptorW(L"O:SYG:SYD:(A;;0x3;;;WD)(A;;0x1;;;S-1-15-2-1)(A;;0x2;;;S-1-15-2-2)",SDDL_REVISION_1,&sd,nullptr),"sd");
